/* ----------------------------------------------------------------------------
   2. ROUTER — hash-based, but now synced to the real URL (#/page/param) so
   the browser back/forward buttons work and links are shareable/deep-linkable.
   NOTE ON REACT ROUTER: react-router-dom isn't in this sandbox's available
   package set for live artifacts, so a full migration isn't possible here.
   When this moves into a real build (Vite/Next), swap this hook for
   `useNavigate()`/`useParams()` and the <A> component for <Link> — every
   call site already matches that shape 1:1, so the swap is mechanical.
---------------------------------------------------------------------------- */

function parseHash() {
  const raw = (typeof window !== "undefined" ? window.location.hash : "") || "#/home";
  const parts = raw.replace(/^#\/?/, "").split("/").filter(Boolean);
  return { page: parts[0] || "home", param: parts[1] ? decodeURIComponent(parts[1]) : null };
}

function useRouter() {
  const [route, setRoute] = useState(() => parseHash());

  const navigate = useCallback((page, param = null) => {
    const hash = `#/${page}${param ? "/" + encodeURIComponent(param) : ""}`;
    if (window.location.hash !== hash) {
      window.location.hash = hash;
    } else {
      setRoute({ page, param });
    }
    window.scrollTo({ top: 0, behavior: "auto" });
  }, []);

  useEffect(() => {
    const onHashChange = () => setRoute(parseHash());
    window.addEventListener("hashchange", onHashChange);
    return () => window.removeEventListener("hashchange", onHashChange);
  }, []);

  // Basic per-page SEO: document title + meta description.
  useEffect(() => {
    const meta = PAGE_META[route.page] || PAGE_META.home;
    if (typeof document !== "undefined") {
      document.title = meta.title;
      let tag = document.querySelector('meta[name="description"]');
      if (!tag) {
        tag = document.createElement("meta");
        tag.setAttribute("name", "description");
        document.head.appendChild(tag);
      }
      tag.setAttribute("content", meta.desc);
    }
  }, [route.page]);

  return { route, navigate };
}

/* ----------------------------------------------------------------------------
   3. SHARED PRIMITIVES
---------------------------------------------------------------------------- */

function useReveal() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    if (typeof IntersectionObserver === "undefined") {
      setVisible(true);
      return;
    }
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisible(true);
            obs.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.15 }
    );
    obs.observe(node);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}

function Reveal({ children, delay = 0, className = "", as: Tag = "div" }) {
  const [ref, visible] = useReveal();
  return (
    <Tag
      ref={ref}
      className={`reveal ${visible ? "is-visible" : ""} ${className}`}
      style={{ transitionDelay: visible ? `${delay}ms` : "0ms" }}
    >
      {children}
    </Tag>
  );
}

