function PlaceholderImage({ label, ratio = "4 / 3", tone = "sand", icon: Icon = ImageIcon, className = "", rounded = "rounded-lg" }) {
  const realSrc = IMAGE_LIBRARY[label];

  if (realSrc) {
    return (
      <div className={`ph-media ph-media-real ${rounded} ${className}`} style={{ aspectRatio: ratio }}>
        <img src={realSrc} alt={label.replace(/—/g, "-")} loading="lazy" />
      </div>
    );
  }

  const dark = tone !== "sand";
  return (
    <div
      className={`ph-media ${rounded} ${className}`}
      style={{ aspectRatio: ratio, background: TONE_GRADIENTS[tone] || TONE_GRADIENTS.sand }}
      role="img"
      aria-label={`Placeholder image: ${label}`}
    >
      <span className="ph-pattern" aria-hidden="true" />
      <span className={`ph-content ${dark ? "is-dark" : ""}`}>
        <Icon size={26} strokeWidth={1.25} aria-hidden="true" />
        <span className="ph-label">{label}</span>
      </span>
    </div>
  );
}

function CoordStamp({ label, className = "" }) {
  return (
    <div className={`coord-stamp ${className}`} aria-hidden="true">
      <span className="coord-stamp-ring">
        <Compass size={13} strokeWidth={1.4} />
      </span>
      <span className="coord-stamp-text">{label}</span>
    </div>
  );
}

function Eyebrow({ children, tone = "gold" }) {
  return <span className={`eyebrow eyebrow-${tone}`}>{children}</span>;
}

function ContourDivider({ tone = "earth" }) {
  return (
    <div className={`contour-divider contour-${tone}`} aria-hidden="true">
      <svg viewBox="0 0 1200 40" preserveAspectRatio="none">
        <path d="M0 20 C 150 40, 300 0, 450 20 S 750 40, 900 20 S 1150 0, 1200 20" />
      </svg>
    </div>
  );
}

function Button({ children, variant = "primary", onClick, href, type = "button", icon: Icon, className = "", ...rest }) {
  const cls = `btn btn-${variant} ${className}`;
  const content = (
    <>
      <span>{children}</span>
      {Icon ? <Icon size={17} strokeWidth={2} aria-hidden="true" /> : null}
    </>
  );
  if (href) {
    return (
      <a href={href} className={cls} {...rest}>
        {content}
      </a>
    );
  }
  return (
    <button type={type} className={cls} onClick={onClick} {...rest}>
      {content}
    </button>
  );
}

function A({ page, param, navigate, className = "", children, ...rest }) {
  return (
    <a
      href={`#/${page}${param ? "/" + encodeURIComponent(param) : ""}`}
      className={className}
      onClick={(e) => {
        e.preventDefault();
        navigate(page, param);
      }}
      {...rest}
    >
      {children}
    </a>
  );
}

function SectionIntro({ eyebrow, title, lede, tone = "gold", align = "left" }) {
  return (
    <Reveal className={`section-intro align-${align}`}>
      {eyebrow ? <Eyebrow tone={tone}>{eyebrow}</Eyebrow> : null}
      <h2 className="section-title">{title}</h2>
      {lede ? <p className="section-lede">{lede}</p> : null}
    </Reveal>
  );
}

function DemoContentNote({ children }) {
  return (
    <div className="demo-note" role="note">
      <AlertTriangle size={14} aria-hidden="true" />
      <span>{children}</span>
    </div>
  );
}

/* ----------------------------------------------------------------------------
   4. NAVIGATION, FOOTER, GLOBAL WIDGETS
---------------------------------------------------------------------------- */

function Navbar({ route, navigate }) {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const isHome = route.page === "home";
  const transparent = isHome && !scrolled && !menuOpen;

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => setMenuOpen(false), [route.page, route.param]);

  useEffect(() => {
    document.body.style.overflow = menuOpen ? "hidden" : "";
    return () => { document.body.style.overflow = ""; };
  }, [menuOpen]);

  return (
    <header className={`navbar ${transparent ? "navbar-transparent" : "navbar-solid"} ${menuOpen ? "navbar-menu-open" : ""}`}>
      <div className="navbar-inner">
        <A page="home" navigate={navigate} className="brand" aria-label={`${SITE_CONFIG.business.name} — home`}>
          <span className="brand-mark" aria-hidden="true">{SITE_CONFIG.business.monogram}</span>
          <span className="brand-word">
            {SITE_CONFIG.business.lineOne}<span className="brand-sub">{SITE_CONFIG.business.lineTwo}</span>
          </span>
        </A>

        <nav className="nav-desktop" aria-label="Primary">
          {NAV_LINKS.map((link) => (
            <A
              key={link.page}
              page={link.page}
              navigate={navigate}
              className={`nav-link ${route.page === link.page ? "is-active" : ""}`}
              aria-current={route.page === link.page ? "page" : undefined}
            >
              {link.label}
            </A>
          ))}
        </nav>

        <div className="navbar-actions">
          <Button variant="primary" className="nav-cta" onClick={() => navigate("experiences")}>
            Book Now
          </Button>
          <button
            className="nav-burger"
            aria-label={menuOpen ? "Close menu" : "Open menu"}
            aria-expanded={menuOpen}
            aria-controls="mobile-menu"
            onClick={() => setMenuOpen((v) => !v)}
          >
            {menuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>
      </div>

      <div id="mobile-menu" className={`nav-mobile ${menuOpen ? "is-open" : ""}`}>
        <nav aria-label="Mobile" className="nav-mobile-links">
          {NAV_LINKS.map((link, i) => (
            <A
              key={link.page}
              page={link.page}
              navigate={navigate}
              className={`nav-mobile-link ${route.page === link.page ? "is-active" : ""}`}
              style={{ transitionDelay: menuOpen ? `${i * 35}ms` : "0ms" }}
            >
              {link.label}
            </A>
          ))}
        </nav>
        <Button variant="primary" className="nav-mobile-cta" onClick={() => navigate("experiences")}>
          Book Now
        </Button>
      </div>
    </header>
  );
}

