/* ----------------------------------------------------------------------------
   5. BOOKING MODAL — explicitly a request form, not a live booking engine.
   There is no backend yet (see audit). Flip SITE_CONFIG.BOOKING_BACKEND_CONNECTED
   only once a real API exists, and swap the onSubmit below for a real POST.
---------------------------------------------------------------------------- */

function BookingModal({ item, onClose }) {
  const [step, setStep] = useState("form");
  const [guests, setGuests] = useState(2);
  const dialogRef = useRef(null);

  useEffect(() => {
    if (!item) return;
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    document.addEventListener("keydown", onKey);
    document.body.style.overflow = "hidden";
    const t = setTimeout(() => dialogRef.current?.focus(), 10);
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
      clearTimeout(t);
    };
  }, [item, onClose]);

  useEffect(() => { if (item) setStep("form"); }, [item]);

  if (!item) return null;

  const destName = item.destinationName || DESTINATIONS.find((d) => d.id === item.destinationSlug)?.name;

  return (
    <div className="modal-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="modal booking-modal" role="dialog" aria-modal="true" aria-labelledby="booking-title" tabIndex={-1} ref={dialogRef}>
        <button className="modal-close" onClick={onClose} aria-label="Close booking dialog"><X size={20} /></button>

        {step === "form" && (
          <>
            <Eyebrow tone="teal">Reserve your place</Eyebrow>
            <h3 id="booking-title" className="modal-title">{item.title || item.name}</h3>
            <p className="modal-sub">
              {destName ? `${destName} · ` : ""}{item.price || item.priceRange || ""}
            </p>

            <form
              className="booking-form"
              onSubmit={(e) => {
                e.preventDefault();
                // No backend is connected yet — this only advances local UI
                // state. See SITE_CONFIG.BOOKING_BACKEND_CONNECTED.
                setStep("confirmed");
              }}
            >
              <div className="field-row">
                <div className="field">
                  <label htmlFor="bk-date">Travel date</label>
                  <input id="bk-date" name="date" type="date" required />
                </div>
                <div className="field">
                  <label htmlFor="bk-guests">Guests</label>
                  <div className="stepper">
                    <button type="button" aria-label="Decrease guests" onClick={() => setGuests((g) => Math.max(1, g - 1))}>−</button>
                    <span id="bk-guests" aria-live="polite">{guests}</span>
                    <button type="button" aria-label="Increase guests" onClick={() => setGuests((g) => Math.min(16, g + 1))}>+</button>
                  </div>
                </div>
              </div>
              <div className="field">
                <label htmlFor="bk-name">Full name</label>
                <input id="bk-name" name="name" type="text" required placeholder="Jane Traveller" />
              </div>
              <div className="field">
                <label htmlFor="bk-email">Email</label>
                <input id="bk-email" name="email" type="email" required placeholder="you@email.com" />
              </div>
              <div className="field">
                <label htmlFor="bk-notes">Notes (optional)</label>
                <textarea id="bk-notes" name="notes" rows={2} placeholder="Dietary needs, arrival time, special requests…" />
              </div>
              <p className="booking-note">
                This is a request form, not a live booking — nothing is charged or reserved yet.
                Submitting sends a request our team confirms by email within 24 hours.
              </p>
              <Button type="submit" variant="primary" className="booking-submit">Request to Book</Button>
            </form>
          </>
        )}

        {step === "confirmed" && (
          <div className="booking-confirmed">
            <span className="confirm-icon"><Check size={26} /></span>
            <h3 className="modal-title">Request sent</h3>
            <p>
              Thanks — we've received your request for <strong>{item.title || item.name}</strong> ({guests} guest{guests > 1 ? "s" : ""}).
              A member of our team will confirm availability and next steps by email.
            </p>
            <Button variant="secondary" onClick={onClose}>Done</Button>
          </div>
        )}
      </div>
    </div>
  );
}

